values
('bmlt-anaerobic-special-pathogens-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1800,$json${"question":"Which organism is a major cause of intra-abdominal anaerobic infections?","translation":"","options":["Bacteroides fragilis","Neisseria gonorrhoeae","Vibrio cholerae","Bordetella pertussis"],"correctIndex":0,"explanation":"B. fragilis is a common anaerobic component of intestinal flora and can cause abscesses after mucosal disruption.","explanationNe":"B. fragilis आन्द्राको flora मा पाइन्छ र mucosal barrier बिग्रँदा abscess गराउन सक्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',1801,$json${"question":"Which atmosphere is required for growth of strict anaerobes?","translation":"","options":["Oxygen-free or very low oxygen","High oxygen","High carbon dioxide only","Atmospheric nitrogen with abundant oxygen"],"correctIndex":0,"explanation":"Strict anaerobes are inhibited or killed by oxygen exposure.","explanationNe":"Strict anaerobes oxygen मा रोकिन वा नष्ट हुन सक्छन्।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',1802,$json${"question":"Which specimen is generally preferred for anaerobic culture from a deep abscess?","translation":"","options":["Aspirated pus in an anaerobic transport system","Superficial dry swab","Saliva","Urine from collection bag"],"correctIndex":0,"explanation":"Aspirates or tissue are preferred over superficial swabs and should be protected from oxygen.","explanationNe":"गहिरो abscess बाट aspirate वा tissue राम्रो हुन्छ; oxygen बाट जोगाउनुपर्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',1803,$json${"question":"Which transport condition is important for anaerobic specimens?","translation":"","options":["Rapid transport in oxygen-free transport medium","Leave uncapped in air","Refrigerate open container","Expose to sunlight"],"correctIndex":0,"explanation":"Anaerobic transport systems minimize oxygen exposure and preserve viability.","explanationNe":"Anaerobic transport medium ले oxygen exposure घटाई जीवाणु जीवित राख्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',1804,$json${"question":"Which organism is associated with antibiotic-associated pseudomembranous colitis?","translation":"","options":["Clostridioides difficile","Clostridium tetani","Clostridium botulinum","Bacillus anthracis"],"correctIndex":0,"explanation":"C. difficile produces toxins that can cause antibiotic-associated colitis.","explanationNe":"C. difficile को toxin ले antibiotic-associated colitis गराउन सक्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',1805,$json${"question":"Which toxin causes the spastic paralysis of tetanus?","translation":"","options":["Tetanospasmin","Botulinum toxin","Shiga toxin","Cholera toxin"],"correctIndex":0,"explanation":"Tetanospasmin blocks inhibitory neurotransmitter release, causing muscle rigidity and spasms.","explanationNe":"Tetanospasmin ले inhibitory neurotransmitter release रोक्दा मांसपेशी कडापन र ऐंठन हुन्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',1806,$json${"question":"Botulinum neurotoxin causes which type of paralysis?","translation":"","options":["Flaccid paralysis","Spastic paralysis","No paralysis","Sensory-only loss"],"correctIndex":0,"explanation":"Botulinum toxin blocks acetylcholine release at the neuromuscular junction, causing flaccid paralysis.","explanationNe":"Botulinum toxin ले neuromuscular junction मा acetylcholine release रोक्छ र flaccid paralysis गराउँछ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',1807,$json${"question":"Which organism is classically associated with gas gangrene?","translation":"","options":["Clostridium perfringens","Clostridioides difficile","Clostridium tetani","Bacteroides fragilis"],"correctIndex":0,"explanation":"C. perfringens produces tissue-damaging toxins and can cause clostridial myonecrosis.","explanationNe":"C. perfringens का toxin ले tissue नष्ट गरी gas gangrene गराउन सक्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',1808,$json${"question":"Which laboratory finding may support C. perfringens in a wound specimen?","translation":"","options":["Large Gram-positive rods with spores rarely seen in tissue","Gram-negative diplococci","Acid-fast branching rods","Budding yeast only"],"correctIndex":0,"explanation":"C. perfringens appears as large Gram-positive rods; spores may not be evident in clinical material.","explanationNe":"C. perfringens ठूला Gram-positive rods जस्ता देखिन्छन्; clinical sample मा spores नदेखिन सक्छन्।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',1809,$json${"question":"Which organism is a branching Gram-positive anaerobic bacterium associated with cervicofacial infections?","translation":"","options":["Actinomyces israelii","Nocardia asteroides","Mycobacterium tuberculosis","Legionella pneumophila"],"correctIndex":0,"explanation":"Actinomyces israelii can cause chronic cervicofacial actinomycosis and sulfur granules.","explanationNe":"Actinomyces israelii ले chronic cervicofacial infection र sulfur granules बनाउन सक्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',1810,$json${"question":"Which feature helps distinguish Nocardia from Actinomyces?","translation":"","options":["Nocardia is weakly acid-fast","Actinomyces is strongly acid-fast","Nocardia is a virus","Actinomyces is a fungus"],"correctIndex":0,"explanation":"Nocardia is aerobic and weakly acid-fast; Actinomyces is generally anaerobic and non-acid-fast.","explanationNe":"Nocardia aerobic र weakly acid-fast हुन्छ; Actinomyces प्रायः anaerobic र non-acid-fast हुन्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',1811,$json${"question":"Which stain is useful for demonstrating weak acid-fastness of Nocardia?","translation":"","options":["Modified acid-fast stain","India ink","Albert stain","Wright stain"],"correctIndex":0,"explanation":"A modified acid-fast method can demonstrate the partially acid-fast Nocardia filaments.","explanationNe":"Modified acid-fast stain ले Nocardia का partially acid-fast filament देखाउन सक्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',1812,$json${"question":"Which organism is associated with foul-smelling infections and is part of normal colonic flora?","translation":"","options":["Bacteroides fragilis group","Streptococcus pyogenes","Neisseria meningitidis","Corynebacterium diphtheriae"],"correctIndex":0,"explanation":"Bacteroides species are normal gut flora and can cause polymicrobial foul-smelling abscesses.","explanationNe":"Bacteroides आन्द्राको सामान्य flora हो र mixed foul-smelling abscess गराउन सक्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',1813,$json${"question":"Which organism is classically associated with dental plaque and aspiration-related lung abscesses?","translation":"","options":["Prevotella species","Salmonella Typhi","Vibrio cholerae","Shigella sonnei"],"correctIndex":0,"explanation":"Prevotella species are oral anaerobes implicated in periodontal and aspiration-related infections.","explanationNe":"Prevotella मुखको anaerobic flora हो र periodontal तथा aspiration infection मा संलग्न हुन सक्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',1814,$json${"question":"Which specimen is unsuitable for reliable anaerobic culture?","translation":"","options":["Superficial swab exposed to air","Deep tissue biopsy","Needle aspirate","Sterile body fluid collected anaerobically"],"correctIndex":0,"explanation":"Superficial swabs are easily contaminated and exposed to oxygen; aspirates or tissue are preferred.","explanationNe":"हावामा खुला superficial swab oxygen र contaminant का कारण anaerobic culture का लागि उपयुक्त हुँदैन।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
('bmlt-anaerobic-special-pathogens-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',1815,$json${"question":"Which indicator is commonly used to monitor oxygen exposure in an anaerobic jar?","translation":"","options":["Resazurin or methylene blue indicator","Phenolphthalein only","Neutral red only","Safranin"],"correctIndex":0,"explanation":"Redox indicators help verify that the anaerobic environment has been achieved.","explanationNe":"Redox indicator ले anaerobic वातावरण बनेको छ कि छैन देखाउन मद्दत गर्छ।","topic":"Anaerobic Bacteriology and Special Pathogens"}$json$::jsonb,true),
